#include "InheritedBase.inc"
#include <chrono>
int main(int argc,char**argv){try{
 if(argc!=5)throw std::invalid_argument("SDK SCENE FRAME BEAM");sofa::simulation::graph::init();sofa::simpleapi::init();sofa::helper::system::PluginRepository.addFirstPath(std::string(argv[1])+"/lib");sofa::simulation::Simulation::theSimulation=sofa::simpleapi::createSimulation("DAG");if(!sofa::simpleapi::importPlugin(argv[3])||!sofa::simpleapi::importPlugin(argv[4]))throw std::runtime_error("plugin");auto root=sofa::simulation::node::load(argv[2]);if(!root)throw std::runtime_error("scene");sofa::simulation::node::initRoot(root.get());auto start=std::chrono::steady_clock::now();for(int i=0;i<8000;++i)sofa::simulation::node::animate(root.get());double duration=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();auto*body=root->getChild("Multilayer");auto*state=dynamic_cast<State*>(body->getMechanicalState());auto original=state->read(sofa::core::vec_id::read_access::position)->getValue();auto*v=state->read(sofa::core::vec_id::read_access::velocity);std::cout<<std::setprecision(17)<<"PROFILE_STEPS {\"steps\":8000,\"wall\":"<<duration<<",\"nodes\":"<<original.size()<<"}"<<std::endl;
 for(auto*ff:static_cast<sofa::core::objectmodel::BaseContext*>(body)->getObjects<FF>(sofa::core::objectmodel::BaseContext::Local))for(bool alternating:{false,true}){auto begin=std::chrono::steady_clock::now();for(int i=0;i<100;++i){auto x=original;if(alternating)x[1].getCenter()[0]+=(i%2?1:-1)*1e-9;FF::DataVecCoord xd;xd.setValue(x);FF::DataVecDeriv f;f.setValue(Types::VecDeriv(x.size()));sofa::core::MechanicalParams mp;ff->addForce(&mp,f,xd,*v);}double us=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()*1e4;std::cout<<"PROFILE_FIELD {\"class\":\""<<ff->getClassName()<<"\",\"name\":\""<<ff->getName()<<"\",\"alternating_pose\":"<<alternating<<",\"us_per_query\":"<<us<<"}"<<std::endl;}
 sofa::simulation::node::unload(root);root.reset();sofa::simulation::Simulation::theSimulation.reset();sofa::simpleapi::cleanup();sofa::simulation::graph::cleanup();return 0;
}catch(const std::exception&e){std::cerr<<"[ERROR] "<<e.what()<<std::endl;return 1;}}
